"""Accessible, offline model markup for the eight tutorial chapters."""
def model(title, description, controls, result, note, graphic=''):
    return f'<div class="lab"><div class="lab-label">Explore the idea</div><h3>{title}</h3><p>{description}</p><div class="controls">{controls}</div>{graphic}<div class="readout" id="{result}" role="status" aria-live="polite"></div><p class="model-note">{note}</p></div>'
def number(id,label,value,min='0',max='1000000',step='any'):
    return f'<label for="{id}">{label}<input id="{id}" type="number" value="{value}" min="{min}" max="{max}" step="{step}"></label>'
MODELS = {
'skills':model('Mass and volume, connected','Change either measurement and predict the effect on density.',number('densityMass','Mass / g','27.0')+number('densityVolume','Volume / mL','10.0',min='0.000001'),'densityResult','The model uses a uniform sample. Unit conversions do not add measurement precision.'),
'matter':model('Build an ionic formula','Choose ions and watch their charges balance in the smallest whole-number ratio.','<label for="cation">Cation<select id="cation"><option value="0">Calcium · Ca²⁺</option><option value="1">Aluminum · Al³⁺</option><option value="2">Iron(III) · Fe³⁺</option><option value="3">Ammonium · NH₄⁺</option></select></label><label for="anion">Anion<select id="anion"><option value="0">Chloride · Cl⁻</option><option value="1">Oxide · O²⁻</option><option value="2">Sulfate · SO₄²⁻</option><option value="3">Nitrate · NO₃⁻</option></select></label>','ionicResult','This is a charge-balance model for ionic formula writing, not a prediction that every pair forms a stable compound under all conditions.'),
'mole':model('Mass → moles → particles','Choose a substance and enter a sample mass.','<label for="moleSubstance">Substance<select id="moleSubstance"><option value="0">H₂O · 18.02 g mol⁻¹</option><option value="1">CO₂ · 44.01 g mol⁻¹</option><option value="2">NaCl · 58.44 g mol⁻¹</option><option value="3">O₂ · 32.00 g mol⁻¹</option></select></label>'+number('moleMass','Sample mass / g','18.02'),'moleResult','Uses the displayed rounded molar masses and exact Nₐ. Readouts show extra digits to explore proportionality; round final answers to the precision of measured inputs.'),
'reactions':model('Find the limiting reactant','For 2H₂ + O₂ → 2H₂O, change the available moles.',number('hydrogen','Initial H₂ / mol','5.00',max='100')+number('oxygen','Initial O₂ / mol','2.00',max='100'),'limitingResult','Assumes complete conversion by this reaction, without side reactions. H₂O amount does not specify its phase.'),
'atoms':model('Wavelength and photon energy','Shorter wavelength means higher energy per photon.','<label for="wavelength">Wavelength: <output id="waveValue" for="wavelength">486</output> nm<input id="wavelength" type="range" min="380" max="750" value="486" step="1"></label>','photonResult','This continuous wavelength explorer illustrates E = hc/λ. An atom’s emission spectrum contains only its allowed transition wavelengths.', '<svg id="waveGraphic" viewBox="0 0 540 95" role="img" aria-label="Light wave: the wavelength changes with the slider"><path id="wavePath" d="" fill="none" stroke="#235b47" stroke-width="3"/><line x1="10" y1="48" x2="530" y2="48" stroke="#b9c8ab" stroke-dasharray="4 5"/></svg>'),
'bonding':model('See shape and polarity together','Choose a molecule and connect its Lewis count to its geometry.','<label for="shape">Molecule<select id="shape"><option value="CO2">CO₂</option><option value="BF3">BF₃</option><option value="CH4">CH₄</option><option value="NH3">NH₃</option><option value="H2O">H₂O</option><option value="PCl5">PCl₅</option><option value="SF6">SF₆</option></select></label>','shapeResult','Schematic projections show connectivity and domain arrangement. Wedges and dashed bonds indicate depth; sizes and lengths are illustrative.', '<svg id="shapeGraphic" viewBox="0 0 540 250" role="img" aria-label="Selected molecular shape"><g id="shapeDrawing"></g></svg>'),
'solutions':model('Dilution conserves solute','Change the stock concentration, aliquot, or final volume.',number('stockConcentration','Stock c₁ / mol L⁻¹','0.400',max='100')+number('stockVolume','Aliquot V₁ / mL','25.0',min='0.000001',max='100000')+number('finalVolume','Final V₂ / mL','200.0',min='0.000001',max='100000'),'dilutionResult','No loss or chemical reaction; final volume must be at least the starting aliquot for this dilution model.'),
'organic':model('Build a straight-chain alkane','Every extra internal carbon adds one carbon and two hydrogens.','<label for="carbonCount">Carbon atoms: <output id="carbonValue" for="carbonCount">5</output><input id="carbonCount" type="range" min="1" max="10" step="1" value="5"></label>','organicResult','Neutral, open-chain, unbranched alkanes only. The sketch labels carbon atoms; hydrogen atoms are omitted and supplied by normal carbon valence.', '<svg id="chainGraphic" viewBox="0 0 540 110" role="img" aria-label="Carbon chain with implicit hydrogen atoms"><g id="chainDrawing"></g></svg>')
}
